import React, { useEffect, useMemo, useState } from "react";
import { onValue, query, ref } from "firebase/database";
import { db } from "./firebase";
import StatusCard from "./components/StatusCard";
import ActivityLog from "./components/ActivityLog";

function toDisplayTime(timestamp) {
  if (!timestamp) return "-";
  return new Date(timestamp).toLocaleString();
}

export default function App() {
  const [lockerData, setLockerData] = useState({
    status: "safe",
    door: "closed",
    vibration: "none",
    last_updated: null
  });
  const [events, setEvents] = useState([]);
  const [now, setNow] = useState(Date.now());
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    const lockerRef = ref(db, "lockers/locker_01");
    const eventsRef = query(ref(db, "events"));

    const unsubLocker = onValue(lockerRef, (snapshot) => {
      const value = snapshot.val();
      if (value) {
        setLockerData((prev) => ({ ...prev, ...value }));
      }
    });

    const unsubEvents = onValue(eventsRef, (snapshot) => {
      const value = snapshot.val() || {};
      const parsed = Object.entries(value)
        .map(([id, data]) => ({
          id,
          type: data?.type || "unknown_event",
          timestamp: data?.timestamp || 0
        }))
        .sort((a, b) => b.timestamp - a.timestamp);

      setEvents(parsed);
    });

    return () => {
      unsubLocker();
      unsubEvents();
    };
  }, []);

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  const connectionState = useMemo(() => {
    if (!lockerData.last_updated) return "ESP32 Offline";
    return now - lockerData.last_updated > 30000 ? "ESP32 Offline" : "ESP32 Connected";
  }, [lockerData.last_updated, now]);

  return (
    <div className={`app-shell ${darkMode ? "theme-dark" : "theme-light"}`}>
      <header className="app-header">
        <div>
          <h1>SecureLocker Dashboard</h1>
          <p className="subtitle">Real-time IoT monitoring for locker security</p>
        </div>
        <button className="theme-toggle" onClick={() => setDarkMode((v) => !v)}>
          {darkMode ? "Switch to Light" : "Switch to Dark"}
        </button>
      </header>

      <main className="grid-layout">
        <StatusCard
          lockerStatus={lockerData.status || "safe"}
          doorState={lockerData.door || "closed"}
          vibrationState={lockerData.vibration || "none"}
          lastUpdated={toDisplayTime(lockerData.last_updated)}
          connectionState={connectionState}
        />
        <ActivityLog events={events} />
      </main>
    </div>
  );
}
